 ModelQuota ActiveQuota {get{return liveUsage==null?null:liveUsage.Models.FirstOrDefault(m=>m.ModelKey==activeModelKey);}}
 void DrawUsage(){var q=ActiveQuota;string model=q==null?"Model allowance":q.Label;string quota=q==null?"Not reported":q.RemainingText+" remaining";quotaSummary.Text=model+Environment.NewLine+quota+"  ·  Today: "+budget.Used(DateTime.UtcNow)+(settings.DailySendBudget==0?" / unlimited":" / "+settings.DailySendBudget);quotaSummary.ForeColor=q!=null&&q.Remaining.HasValue&&q.Remaining<=0?Color.FromArgb(244,150,150):Theme.Muted;}
 async Task RefreshUsage(){if(usageLoading||accountOperation||closing)return;usageLoading=true;try{var c=conversations.SelectedItem as Conversation;if(c==null)return;liveUsage=UsageSnapshot.FromJson(await c.Endpoint.Call("GetUserStatus",new{}));lastUsageCheck=DateTime.UtcNow;var request=await c.Endpoint.PrepareSend(c,prompt.Text);activeModelKey=UsageSnapshot.ModelKeyFromRequest(request);DrawUsage();
