  try{if(vaultLocked)return;var saved=LoginState.Capture();if(string.Equals(saved.Email,liveUsage.Email,StringComparison.OrdinalIgnoreCase)){saved.Usage=liveUsage;accountVault.Upsert(saved);accountVault.Save();}}catch{ /* A readable quota does not imply reusable login credentials. */ }
 }catch{quotaSummary.Text="Usage unavailable · Open Usage & accounts";}finally{usageLoading=false;}}
 async Task<bool> CheckAllowance(Conversation current){int run=epoch;if(!budget.CanSend(settings.DailySendBudget,DateTime.UtcNow)){Stop("Daily request budget reached. Resets at midnight IST.");DrawUsage();return false;}
 try{liveUsage=UsageSnapshot.FromJson(await current.Endpoint.Call("GetUserStatus",new{}));var request=await current.Endpoint.PrepareSend(current,prompt.Text);if(run!=epoch||!engine.Armed)return false;activeModelKey=UsageSnapshot.ModelKeyFromRequest(request);lastUsageCheck=DateTime.UtcNow;DrawUsage();
 var q=ActiveQuota;if(!RotationPolicy.Exhausted(q))return true;
 if(!settings.AutoSwitchAccounts){Stop("Model quota exhausted. Enable account switching or wait for quota reset.");return false;}
 var exhausted=accountVault.Accounts.FirstOrDefault(a=>string.Equals(a.Email,liveUsage.Email,StringComparison.OrdinalIgnoreCase));if(exhausted!=null){exhausted.Usage=liveUsage;exhausted.SavedUtc=DateTime.UtcNow;rotationAttempts.Add(exhausted.Id);if(!vaultLocked)accountVault.Save();}
 var next=RotationPolicy.Next(accountVault.Accounts,liveUsage.Email,q.Label,DateTime.UtcNow,rotationAttempts);if(next==null){Stop("Quota exhausted. No other saved login has available quota for this model.");return false;}rotationAttempts.Add(next.Id);await SwitchLogin(next,true);return false;
 }catch{if(run==epoch&&engine.Armed)Stop("Could not verify usage before sending. Refresh Usage & accounts, then resume.");return false;}}
 async Task SwitchLogin(LoginAccount target,bool resume){
  if(accountOperation)return;
  if(liveUsage!=null&&string.Equals(liveUsage.Email,target.Email,StringComparison.OrdinalIgnoreCase)){Log("Selected login is already active.");return;}
  bool shouldResume=resume&&engine.Armed;Stop("Switching login; waiting for idle agents");int switchEpoch=epoch;accountOperation=true;accountCancellation=new System.Threading.CancellationTokenSource();usageButton.Enabled=false;start.Enabled=false;stop.Enabled=true;
  try{
   for(int attempt=0;attempt<Math.Max(1,accountVault.Accounts.Count);attempt++){
    accountCancellation.Token.ThrowIfCancellationRequested();
    try{var current=LoginState.Capture();if(liveUsage!=null&&string.Equals(current.Email,liveUsage.Email,StringComparison.OrdinalIgnoreCase))current.Usage=liveUsage;accountVault.Upsert(current);accountVault.Save();}catch{throw new InvalidOperationException("Current login could not be backed up. Switching was cancelled.");}
    await AccountSwitcher.Apply(target,accountCancellation.Token);Log("Login changed. Verifying account identity and original conversation.");
    DateTime deadline=DateTime.UtcNow.AddSeconds(60);Conversation restored=null;UsageSnapshot verified=null;
    while(DateTime.UtcNow<deadline&&!closing){accountCancellation.Token.ThrowIfCancellationRequested();await Task.Delay(1500,accountCancellation.Token);try{var all=await DiscoverAll();foreach(var c in all){if(c.Id!=settings.ConversationId)continue;var u=UsageSnapshot.FromJson(await c.Endpoint.Call("GetUserStatus",new{}));if(string.Equals(u.Email,target.Email,StringComparison.OrdinalIgnoreCase)){restored=c;verified=u;break;}}if(restored!=null)break;}catch(System.OperationCanceledException){throw;}catch{}}
    if(restored==null)throw new InvalidOperationException("Login changed, but the new identity and original conversation could not both be verified. Repeating remains stopped. An encrypted previous-login backup is available.");
    liveUsage=verified;int index=conversations.SelectedIndex;if(index>=0){conversations.Items[index]=restored;conversations.SelectedIndex=index;}lastUsageCheck=DateTime.UtcNow;DrawUsage();var saved=LoginState.Capture();saved.Usage=verified;accountVault.Upsert(saved);accountVault.Save();
    var q=ActiveQuota;
    if(shouldResume&&epoch==switchEpoch&&RotationPolicy.Exhausted(q)){
     rotationAttempts.Add(saved.Id);var next=RotationPolicy.Next(accountVault.Accounts,verified.Email,q.Label,DateTime.UtcNow,rotationAttempts);
     if(next!=null){Log("This login also has exhausted quota. Checking another saved login.");target=next;rotationAttempts.Add(next.Id);continue;}
    }
    if(shouldResume&&epoch==switchEpoch&&q!=null&&q.Remaining.HasValue&&q.Remaining.Value>0){engine.ResumeAfterAccountSwitch();sessionStarted=DateTime.UtcNow;SetRunning(true);UpdateStatus();Log("New account verified; continuing the original conversation.");}
    else Stop(RotationPolicy.Exhausted(q)?"No verified saved login has quota for this model. Repeating remains stopped.":"Account verified. Ready to resume.");
    return;
   }
   Stop("Account rotation limit reached. Repeating remains stopped.");
  }catch(OperationCanceledException){Stop("Account switch cancelled. Repeating remains stopped.");}catch(Exception ex){Stop(ex.Message);}finally{accountCancellation.Dispose();accountCancellation=null;accountOperation=false;usageButton.Enabled=true;if(!engine.Armed)SetRunning(false);}
 }

